        Soz("Her duyguya hemen bir karar eklemeden, hissettiklerimi tanımayı öğreniyorum.", "I am learning to recognize my feelings without attaching a decision to each one.", "Ascend", "ic_huzur", sabitKimlik = "v5_ic_huzur_06"),
