        Soz("Sıradan sandığın bir kolaylığın arkasında, birinin sessiz emeği bulunabilir.", "Behind a convenience you take for granted, there may be someone's quiet effort.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_02"),
        Soz("Güzel bir anı hemen fotoğrafa dönüştürmeden önce, içinde biraz daha kalmayı deneyebilirsin.", "Before turning a lovely moment into a photograph, you can try staying in it a little longer.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_03"),
        Soz("Bir iyiliği hatırlamak, zor geçen günün başka renklerini de görmene yardımcı olabilir.", "Remembering a kindness can help you notice other colors in a difficult day.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_04"),
        Soz("Minnettarlık, eksiklerini susturmanı istemez; elindekine de dürüstçe bakacak bir yer açar.", "Gratitude need not silence what is missing; it makes room to honestly notice what is here too.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_05"),
        Soz("Sana yol gösteren birine, hâlâ yanında taşıdığın cümlesini hatırlatabilirsin.", "You can remind someone who guided you of the words you still carry with you.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_06"),
        Soz("Birlikte yapılan sıradan bir işi anmak, ilişkinin görünmez emeğini görünür kılabilir.", "Recalling an ordinary task you did together can make the unseen effort in a relationship visible.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_07"),
        Soz("Günün içinden bir ayrıntı seç: Hangisinin hayatında bulunmasına seviniyorsun?", "Choose a detail from your day: Which one are you glad to have in your life?", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_08"),
        Soz("Kendine teşekkür ederken yalnızca sonuçları sayma; sürdürdüğün özeni de hatırla.", "When thanking yourself, remember the care you kept giving as well as the results.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_09"),
        Soz("İyi gelen bir şeyi fark ettiğinde, onu başkasıyla paylaşarak hatırada biraz daha tutabilirsin.", "When you notice something good, sharing it with someone can keep it in memory a little longer.", "Ascend", "minnettarlik", sabitKimlik = "v5_minnettarlik_10"),
        Soz("Bir lokmanın tadını tam olarak duymak için, elindeki başka işi bir anlığına bırakabilirsin.", "To fully notice the taste of a bite, you can set your other task aside for a moment.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_01"),
        Soz("Yürüdüğün sokakta daha önce fark etmediğin bir çizgiye, gölgeye veya renge bak.", "Look for a line, shadow, or color you have not noticed before on the street you walk.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_02"),
        Soz("Uzaklaşan bir sesin nerede kaybolduğunu dinle; çevrende olup bitenin başlangıcı kadar sonu da fark edilmeye değer.", "Listen for where a fading sound disappears; the endings around you are as available to notice as the beginnings.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_03"),
        Soz("Oturduğun sandalyenin seni taşıyan yüzeyini fark et; içinde bulunduğun yerin somut bir ayrıntısı hep burada.", "Notice the surface of the chair supporting you; a concrete detail of where you are is already within reach.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_04"),
        Soz("Ellerinin yaptığı işe gözlerinle de eşlik et; sıradan bir hareketin ayrıntıları ortaya çıkabilir.", "Let your eyes follow the work of your hands; the details of an ordinary movement may emerge.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_05"),
        Soz("Yağmuru yalnızca havanın durumu olarak geçme; bir damlanın camdaki yolunu izleyebilirsin.", "Rain can be more than a weather report; you can watch a single drop travel down the glass.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_06"),
        Soz("Beklerken geçen zamanı bütünüyle kayıp sayma; çevrende devam eden hayatı fark edebilirsin.", "Time spent waiting need not be entirely lost; you can notice the life continuing around you.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_07"),
        Soz("Bir şarkı çalarken başka bir yere yetişmeden, yalnızca bu nakarat boyunca dinlemeyi dene.", "While a song plays, try listening through this chorus without rushing on to something else.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_08"),
        Soz("Şu anın kusursuz olması gerekmez; içindeki gerçek bir ayrıntıyla yine de temas kurabilirsin.", "This moment need not be perfect; you can still connect with one real detail within it.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_09"),
        Soz("Bir konuşma bittiğinde, yenisine geçmeden önce duyduklarının sende bıraktığı izi fark et.", "When a conversation ends, notice the trace it leaves in you before moving to the next one.", "Ascend", "simdiki_an", sabitKimlik = "v5_simdiki_an_10"),
        Soz("Akşamın son saatine daha az görev bırakmak, geceye geçişin için yer açabilir.", "Leaving fewer tasks for the last hour of the evening can make room for the transition to night.", "Ascend", "uyku", sabitKimlik = "v5_uyku_01"),
        Soz("Yarım kalan bir düşünceyi not edip, onu sabah yeniden ele almak üzere bırakabilirsin.", "You can note an unfinished thought and leave it to be considered again in the morning.", "Ascend", "uyku", sabitKimlik = "v5_uyku_02"),
        Soz("Uykuya yaklaşırken odanın ışığını azaltmak, günün hızından ayrılmanın sade bir işareti olabilir.", "Dimming the room as bedtime approaches can be a simple sign of leaving the day's pace behind.", "Ascend", "uyku", sabitKimlik = "v5_uyku_03"),
        Soz("Bu gece dinlenmeye hazırlanırken, kendinden yeni bir başarı beklememeyi deneyebilirsin.", "As you prepare to rest tonight, you can try asking no new achievement of yourself.", "Ascend", "uyku", sabitKimlik = "v5_uyku_04"),
        Soz("Ekrandaki bir sonraki içeriğe geçmeden önce, akşamı nerede bitirmek istediğini sor.", "Before moving to the next thing on your screen, ask where you want your evening to end.", "Ascend", "uyku", sabitKimlik = "v5_uyku_05"),
        Soz("Bir gece zor geçti diye kendine sert davranma; yorgunluğun daha fazla özeni hak eder.", "Try not to treat yourself harshly after a difficult night; your tiredness deserves extra care.", "Ascend", "uyku", sabitKimlik = "v5_uyku_06"),
        Soz("Yatmadan önce aynı sakin uğraşa dönmek, sana tanıdık bir akşam köşesi sunabilir.", "Returning to the same quiet activity before bed can offer you a familiar corner of the evening.", "Ascend", "uyku", sabitKimlik = "v5_uyku_07"),
        Soz("Yatağa uzandığında yarının konuşmasını prova etmek zorunda değilsin. O konuşmaya yarın da hazırlanabilirsin.", "You need not rehearse tomorrow's conversation in bed. There can be time to prepare for it tomorrow.", "Ascend", "uyku", sabitKimlik = "v5_uyku_08"),
        Soz("Gece sessizleşirken gününü yargılamaya ara verebilir, yatağını dinlenmeye ayırabilirsin.", "As the night grows quiet, you can pause judging your day and reserve your bed for rest.", "Ascend", "uyku", sabitKimlik = "v5_uyku_09"),
        Soz("Uykuya bir yarış gibi yaklaşmadan, kendin için rahat bir gece ortamı hazırlayabilirsin.", "You can prepare a comfortable setting for the night without treating sleep as a race.", "Ascend", "uyku", sabitKimlik = "v5_uyku_10"),
        Soz("Her şeyi karanlık gösteren bir düşünce geldiğinde, henüz bilmediğin ayrıntılara da yer bırak.", "When a thought paints everything dark, leave room for the details you do not yet know.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_01"),
        Soz("Zor geçen bir dönemin içinden bakarken, hayatının tamamını aynı renkle boyamayabilirsin.", "Looking out from a difficult period, you need not paint your whole life in its colors.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_02"),
        Soz("İyi bir ihtimal göremediğinde, güvendiğin birinin gördüklerini dinlemeyi deneyebilirsin.", "When you cannot see a good possibility, you could listen to what someone you trust can see.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_03"),
        Soz("Hevesin azaldığında, sevdiğin bir uğraşla yeniden temas etmek için büyük enerji beklemeyebilirsin.", "When enthusiasm fades, you need not wait for a burst of energy to revisit something you enjoy.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_04"),
        Soz("Bir günün ağırlığını anlatan cümleyi, bütün geleceğinin başlığı yapmak zorunda değilsin.", "A sentence describing the weight of one day need not become the title of your whole future.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_05"),
        Soz("İçinden umutlu sözler gelmiyorsa, dürüst bir ihtiyacını söylemekle başlayabilirsin.", "If hopeful words do not come, you can begin by expressing one honest need.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_06"),
        Soz("Kesin görünen olumsuz bir yargıya, onu desteklemeyen tek bir ayrıntıyı da eklemeyi dene.", "Try adding one detail that does not support a negative judgment that feels certain.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_07"),
        Soz("Dünyanın yükünü sürekli izlerken yorulduysan, haberlerle arana bir mola koyabilirsin.", "If watching the world's burdens leaves you tired, you can put a break between you and the news.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_08"),
        Soz("Bir şeyin henüz değişmemiş olması, değişim için bütün yolları bildiğin anlamına gelmez.", "Something not having changed yet does not mean you know every possible path to change.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_09"),
        Soz("Güzel hissetmeye zorlanmadan da kendine iyi bakabilirsin; bakımın duygunu beklemesi gerekmez.", "You can care for yourself without forcing a good mood; care does not have to wait for a feeling.", "Ascend", "karamsarlik", sabitKimlik = "v5_karamsarlik_10"),
        Soz("Sade bir köşede oturmak bazen gün boyunca dağılmış dikkatini yanına toplar.", "Sitting in a simple corner can sometimes gather the attention you scattered throughout the day.", "Ascend", "huzur", sabitKimlik = "v5_huzur_01"),
        Soz("Hayatındaki her boşluğu doldurmak zorunda değilsin; aralıklar da bir düzenin parçasıdır.", "You do not have to fill every space in your life; gaps can be part of its rhythm too.", "Ascend", "huzur", sabitKimlik = "v5_huzur_02"),
        Soz("Bir tartışmanın ardından hemen son sözü aramak yerine, konuşmaya ara verebilirsin.", "After an argument, you can pause the conversation rather than search for the final word.", "Ascend", "huzur", sabitKimlik = "v5_huzur_03"),
        Soz("Sana iyi gelen sessizliğin biçimini başkaları belirlemek zorunda değil.", "Other people do not have to decide what the quiet that feels good to you should look like.", "Ascend", "huzur", sabitKimlik = "v5_huzur_04"),
        Soz("Evinin bir köşesini sadeleştirirken, orada nasıl hissetmek istediğini düşün.", "As you simplify a corner of your home, think about how you want to feel there.", "Ascend", "huzur", sabitKimlik = "v5_huzur_05"),
        Soz("Bazı akşamların hatırlanacak büyük bir olaya ihtiyacı yoktur; sakinlik de yeterli olabilir.", "Some evenings need no grand event to remember; a sense of ease can be enough.", "Ascend", "huzur", sabitKimlik = "v5_huzur_06"),
        Soz("Sürekli yetişme duygusundan uzak bir yürüyüş, sana kendi hızını yeniden hatırlatabilir.", "A walk free from the feeling of catching up can remind you of your own pace.", "Ascend", "huzur", sabitKimlik = "v5_huzur_07"),
        Soz("Bir konuşmada sesler yükseldiğinde, sakin kalmak için mesafe istemeye hakkın var.", "When voices rise in a conversation, you have a right to ask for space to regain calm.", "Ascend", "huzur", sabitKimlik = "v5_huzur_08"),
        Soz("Huzur ararken, seni sürekli geren bir düzenin değişmesi gereken yanlarını da görebilirsin.", "In seeking peace, you can also notice what needs to change in a routine that keeps you tense.", "Ascend", "huzur", sabitKimlik = "v5_huzur_09"),
        Soz("Sana dinlenme hissi veren bir yeri hatırla; o hissin bir parçasını gününe nasıl taşıyabilirsin?", "Remember a place that lets you feel at ease; how could you bring part of that feeling into your day?", "Ascend", "huzur", sabitKimlik = "v5_huzur_10"),
        Soz("Bir şeyi anlamadığını fark etmek, iyi bir sorunun başlayabileceği verimli bir yerdir.", "Noticing that you do not understand something is fertile ground for a good question.", "Ascend", "merak", sabitKimlik = "v5_merak_01"),
        Soz("Alıştığın bir nesneye yeniden bak: Onu bu biçimde yapmaya kim, neden karar vermiş olabilir?", "Look again at a familiar object: Who might have decided to shape it this way, and why?", "Ascend", "merak", sabitKimlik = "v5_merak_02"),
        Soz("Cevabı bulunca soruyu hemen bırakma; yanıtın hangi yeni kapıyı açtığını da izle.", "When you find an answer, linger with the question and notice which new door it opens.", "Ascend", "merak", sabitKimlik = "v5_merak_03"),
        Soz("Bir fikre katılmadan önce onu anlamaya çalışmak, düşüncelerine daha geniş bir alan kazandırır.", "Trying to understand an idea before agreeing with it gives your thinking more room.", "Ascend", "merak", sabitKimlik = "v5_merak_04"),
        Soz("Bilmediğin bir kelimenin peşinden gitmek, hiç beklemediğin bir konuya yol açabilir.", "Following an unfamiliar word can lead you toward a subject you never expected.", "Ascend", "merak", sabitKimlik = "v5_merak_05"),
        Soz("Bir uzmana yalnızca sonucu sorma; o sonuca nasıl ulaştığını da merak et.", "Ask an expert about more than the result; be curious about how they reached it.", "Ascend", "merak", sabitKimlik = "v5_merak_06"),
        Soz("Merakını yalnızca faydalı görünen şeylere ayırma; şaşırmak da zamanına değer olabilir.", "You need not reserve curiosity for useful things; being surprised can be worth your time too.", "Ascend", "merak", sabitKimlik = "v5_merak_07"),
        Soz("Kesin bildiğin bir düşüncenin yanına, fikrini değiştirebilecek kanıtın ne olacağını yaz.", "Beside a thought you feel certain about, write what evidence could change your mind.", "Ascend", "merak", sabitKimlik = "v5_merak_08"),
        Soz("Aynı yolu yürürken yeni bir ayrıntı aramak, tanıdık dünyayı yeniden keşfetmektir.", "Looking for a new detail along the same route is a way to rediscover a familiar world.", "Ascend", "merak", sabitKimlik = "v5_merak_09"),
        Soz("Bir çocuğun neden sorusuna hemen cevap yetiştirmeden, birlikte araştırmayı deneyebilirsin.", "Instead of rushing to answer a child's why, you can try exploring the question together.", "Ascend", "merak", sabitKimlik = "v5_merak_10"),
        Soz("Bir kitabın sayfaları arasında durmak, okuduklarının kendi hayatınla konuşmasına zaman verir.", "Pausing between a book's pages gives what you read time to speak with your own life.", "Ascend", "okumak", sabitKimlik = "v5_okumak_01"),
        Soz("Sana dokunan bir cümlenin yanına, neden orada durduğunu anlatan birkaç kelime yaz.", "Beside a sentence that moves you, write a few words about why it made you pause.", "Ascend", "okumak", sabitKimlik = "v5_okumak_02"),
        Soz("Okuma hızını bir yarışa çevirmeden, zorlandığın bir paragrafı yeniden ziyaret edebilirsin.", "Without making reading a race, you can return to a paragraph you found difficult.", "Ascend", "okumak", sabitKimlik = "v5_okumak_03"),
        Soz("Bir karakteri anlamaya çalışırken, kendi ilk yargının dışına çıkmayı da deneyebilirsin.", "While trying to understand a character, you can also try stepping outside your first judgment.", "Ascend", "okumak", sabitKimlik = "v5_okumak_04"),
        Soz("Bitirdiğin kitapların sayısı kadar, zihninde yaşamaya devam eden sorular da kıymetlidir.", "The questions that keep living in your mind matter alongside the number of books you finish.", "Ascend", "okumak", sabitKimlik = "v5_okumak_05"),
        Soz("Her kitaba katılman gerekmez; metinle konuşur gibi düşüncelerini kenarına bırakabilirsin.", "You need not agree with every book; leave thoughts in the margin as if talking with the text.", "Ascend", "okumak", sabitKimlik = "v5_okumak_06"),
        Soz("Bir sayfayı sesli okumak, gözünün hızla geçtiği bir ritmi kulağına duyurabilir.", "Reading a page aloud can let your ears hear a rhythm your eyes passed over quickly.", "Ascend", "okumak", sabitKimlik = "v5_okumak_07"),
        Soz("Uzun zamandır okumuyorsan, ilgini gerçekten çeken bir sayfadan yeniden başlayabilirsin.", "If you have not read for a while, you can begin again with a page that truly interests you.", "Ascend", "okumak", sabitKimlik = "v5_okumak_08"),
        Soz("Bir kitabı arkadaşınla konuşurken, onun aynı satırlarda gördüğü başka dünyayı dinle.", "When discussing a book with a friend, listen to the other world they saw in the same lines.", "Ascend", "okumak", sabitKimlik = "v5_okumak_09"),
        Soz("Okuduğun bir düşünceyi gündelik bir olayla ilişkilendirmek, onu raftan hayatına taşır.", "Connecting something you read with an everyday event brings the idea off the shelf and into your life.", "Ascend", "okumak", sabitKimlik = "v5_okumak_10"),
        Soz("Yanlış cevabının yanına bir soru yaz: Düşüncem hangi noktada yön değiştirdi?", "Write a question beside a wrong answer: where did my thinking change direction?", "Ascend", "hata", sabitKimlik = "v5_hata_01"),
        Soz("Notundaki bir düzeltmenin nedenini yanına yaz; yalnızca doğru cevabı değil, değişen düşünceni de sakla.", "Write the reason beside a correction in your notes; keep the change in your thinking alongside the right answer.", "Ascend", "hata", sabitKimlik = "v5_hata_02"),
        Soz("Geri bildirimde işine yarayan kısmı seçmek, kendi emeğine dikkatle bakmaktır.", "Picking out the useful part of feedback means looking carefully at your own work.", "Ascend", "hata", sabitKimlik = "v5_hata_03"),
        Soz("Sildiğin satır boşa gitmiş sayılmaz; hangi yolu eleyeceğini sana göstermiş olabilir.", "An erased line may still have shown you which route to set aside.", "Ascend", "hata", sabitKimlik = "v5_hata_04"),
        Soz("Yanlış çözdüğün soruda doğru ilerlediğin yere kadar geri dön. Düzeltmeye her şeyi silerek başlaman gerekmiyor.", "Return to the last correct step in a wrong solution. You need not erase all your work to fix it.", "Ascend", "hata", sabitKimlik = "v5_hata_05"),
        Soz("Denemenin sonucunu değiştiremeyebilirsin; bir sonraki denemeye götürdüğün soruyu seçebilirsin.", "You may not change a trial's result, but you can choose the question you bring to the next.", "Ascend", "hata", sabitKimlik = "v5_hata_06"),
        Soz("Düzeltmeyi anladığını düşünüyorsan benzer bir soruda dene. Bildiğinle uygulayabildiğin orada buluşur.", "Try a correction on a similar problem. That is where understanding meets what you can actually do.", "Ascend", "hata", sabitKimlik = "v5_hata_07"),
        Soz("Bilmediğini fark ettiğin yerde, öğrenebileceğin şeyin sınırları görünmeye başlar.", "Where you notice a gap in your knowledge, the shape of what you can learn begins to appear.", "Ascend", "hata", sabitKimlik = "v5_hata_08"),
        Soz("Aynı yanlış tekrar ediyorsa, kendine yüklenmeden kullandığın yolu yeniden incele.", "If the same error returns, examine your approach again without piling blame on yourself.", "Ascend", "hata", sabitKimlik = "v5_hata_09"),
        Soz("Düzeltme işaretleriyle dolu bir sayfa, uğraştığın sorunun izlerini taşır.", "A page covered in corrections carries traces of the problem you have been working on.", "Ascend", "hata", sabitKimlik = "v5_hata_10"),
        Soz("Bir davranışın hayatında yer bulması için, başlayacağı anı görünür kılabilirsin.", "To help a behaviour find room in your life, you can make its starting moment visible.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_01"),
        Soz("Okuyacağın kitabı açabileceğin bir yerde bırakmak, niyetine bir adres vermektir.", "Leaving a book where you can open it gives your intention an address.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_02"),
        Soz("Unuttuğun bir günü işaretleyip yoluna dönebilirsin; takvim bir yargıç olmak zorunda değil.", "You can mark a missed day and return; the calendar need not become a judge.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_03"),
        Soz("Alışkanlığını kolaylaştıran ayrıntıları fark et; bazen anahtar, eşyaların yerindedir.", "Notice the details that make a habit easier; sometimes the key is where things are placed.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_04"),
        Soz("Sürdürmek istediğin davranışın en sade hâlini bulmak, yoğun günlere bir kapı bırakır.", "Finding the simplest version of a behaviour leaves a door open on busy days.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_05"),
        Soz("Bir düzen sana uymuyorsa, kendini suçlamadan o düzenin tasarımını değiştirebilirsin.", "If a routine does not fit, you can change its design without blaming yourself.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_06"),
        Soz("Bir alışkanlığın tamamlandığını anlayacağın ölçüyü seç; günün sonunda kendinle belirsiz bir pazarlık yapma.", "Choose a clear sign that a habit is done; leave yourself a finish you can recognise at the end of the day.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_07"),
        Soz("Kendine uygun bir hatırlatıcı, niyetini günün kalabalığında yeniden bulmana yardım edebilir.", "A reminder that suits you can help you find your intention again in a crowded day.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_08"),
        Soz("Bir alışkanlık için seçtiğin yer ve zaman, en az yazdığın hedef kadar somut olabilir.", "The place and time you choose for a habit can be as concrete as the goal you write down.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_09"),
        Soz("Bir alışkanlığı biriyle paylaşırken sana nasıl eşlik etmesini istediğini söyle; destek de sana göre şekillensin.", "When sharing a habit with someone, say how you would like them to join you; let the support fit you too.", "Ascend", "aliskanlik", sabitKimlik = "v5_aliskanlik_10"),
