    private fun bolum9(): List<Soz> = listOf(
        Soz("Bugün zorlanman, dün öğrendiklerini silmiyor. Yeniden denerken onları da yanında götür.", "Struggling today does not erase yesterday's learning. Take it with you when you try again.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_01"),
        Soz("Bir girişimin sonuç vermedi. Sonraki girişimin aynı yerden başlaması gerekmiyor.", "One attempt did not work. Your next attempt does not have to start from the same place.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_02"),
        Soz("Ayağa kalkmak bazen büyük bir karar değil, yarım kalan dosyayı yeniden açmaktır.", "Getting back up can be as ordinary as reopening the file you left unfinished.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_03"),
        Soz("Aynı yolu hemen denemeden önce, nerede takıldığını inceleyebilirsin.", "Before retrying the same route, look at where you got stuck.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_04"),
        Soz("Bir aksilikten sonra hızını düşürmek, devam etmenin bir biçimi olabilir.", "Slowing down after a setback can be one way of continuing.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_05"),
        Soz("Yeniden denemeden önce işe yarayan kısmı koru. Bir başarısızlık, bütün yöntemi çöpe atmanı gerektirmez.", "Before trying again, keep the part that worked. One failure need not make you discard the whole method.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_06"),
        Soz("Bugün yalnızca dağılan parçaları topladıysan, yeniden kurmanın bir bölümünü yaptın.", "If all you did today was gather the scattered pieces, you did part of the rebuilding.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_07"),
        Soz("Başarısızlığını anlatırken, o sırada elinde olmayan bilgiyi de hesaba kat.", "When describing your failure, account for the information you did not have then.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_08"),
        Soz("Tekrar denemeden önce yardım istemek, ilk denemenden çıkardığın bir ders olabilir.", "Asking for help before trying again may be a lesson from your first attempt.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_09"),
        Soz("Bir kez tökezlediğin için her adımını şüpheyle izlemek zorunda değilsin.", "Stumbling once does not mean you have to watch every later step with suspicion.", "Ascend", "dustukten_sonra", sabitKimlik = "v5_dustukten_sonra_10"),
        Soz("Bütün odayı toplamak gözünde büyüyorsa, masanın bir köşesine yer aç.", "If tidying the whole room feels too much, clear one corner of the desk.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_01"),
        Soz("Bir sayfa yazamıyorsan, anlatmak istediğin şeyi tek cümleyle not et.", "If a whole page feels out of reach, write one sentence about what you want to say.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_02"),
        Soz("Bugünün işi büyük planın tamamı olmak zorunda değil; bir sonraki hareketi seç.", "Today's task need not be the whole plan; choose just the next action.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_03"),
        Soz("Beş dakikalık bir iş, zihninde günlerdir kapladığı yerden daha küçük olabilir.", "A five-minute task may be smaller than the space it has occupied in your mind for days.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_04"),
        Soz("Başlamayı kolaylaştır: Defterini arayacağın yerde değil, görebileceğin yerde bırak.", "Make starting easier: leave your notebook where you can see it rather than search for it.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_05"),
        Soz("Uzun bir yolculuğu düşünürken, bugün ulaşabileceğin ilk durağı belirle.", "When thinking about a long journey, identify the first stop you can reach today.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_06"),
        Soz("Küçük hedefin küçük görünmesine izin ver; başkasını etkilemek için büyütmen gerekmiyor.", "Let a small goal look small; you do not need to enlarge it to impress someone else.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_07"),
        Soz("Bir işi parçalara ayırmak onu önemsizleştirmez; elinin uzanabileceği hâle getirir.", "Dividing a task into parts does not make it trivial; it puts it within reach.", "Ascend", "kucuk_adim", sabitKimlik = "v5_kucuk_adim_08"),
