        Soz("Başkalarının ilerlemesi, senin başladığın yere geri döndüğün anlamına gelmez.", "Other people's progress does not mean you have been sent back to where you started.", "Ascend", "kiyas", sabitKimlik = "v5_kiyas_06"),
        Soz("İlk kez denediğin bir beceride, yıllardır yapan birinin rahatlığını beklemeyebilirsin.", "When first trying a skill, you need not expect the ease of someone with years of practice.", "Ascend", "kiyas", sabitKimlik = "v5_kiyas_07"),
        Soz("Kendi yolunun değerini ölçmek için başkasının yolunu küçültmen gerekmiyor.", "You do not need to diminish someone else's path in order to value your own.", "Ascend", "kiyas", sabitKimlik = "v5_kiyas_08"),
        Soz("Sana iyi gelecek hedef, dışarıdan en etkileyici görünen hedef olmayabilir.", "The goal that serves you may not be the one that looks most impressive from outside.", "Ascend", "kiyas", sabitKimlik = "v5_kiyas_09"),
        Soz("Kıyas başladığında soruyu değiştir: Onun nerede olduğundan çok, benim neye ihtiyacım var?", "When comparison begins, change the question: not where are they, but what do I need?", "Ascend", "kiyas", sabitKimlik = "v5_kiyas_10"),
        Soz("Bir eleştiriyi dinlerken, söyleniş biçimiyle içindeki bilgiyi birbirinden ayırabilirsin.", "While listening to criticism, separate its delivery from the information it contains.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_01"),
        Soz("Neyi farklı yapabilirim diye sormak, kendini bütünüyle yanlış ilan etmek değildir.", "Asking what you could do differently does not mean declaring your whole self wrong.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_02"),
        Soz("Genel bir yargı karşısında somut bir örnek istemek, anlamaya çalışmanın bir yoludur.", "Asking for a concrete example of a general judgment is one way of trying to understand.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_03"),
        Soz("Her geri bildirime hemen cevap vermen gerekmiyor; düşünmek için zaman ayırabilirsin.", "You need not respond to every piece of feedback at once; you can take time to think.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_04"),
        Soz("Bir kişinin değerlendirmesi, yaptığın işin bütün hikâyesini tek başına anlatamaz.", "One person's assessment cannot tell the entire story of your work on its own.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_05"),
        Soz("İşe yarayan bir öneriyi alıp incitici bir ifadeyi kabul etmeyebilirsin.", "You can take a useful suggestion without accepting a hurtful way of expressing it.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_06"),
        Soz("Eleştiri canını acıttıysa, bu his geçmeden ders çıkarmaya kendini zorlaman gerekmiyor.", "If criticism hurt, you need not force yourself to find its lesson before the feeling settles.", "Ascend", "elestiri", sabitKimlik = "v5_elestiri_07"),
