        Soz("Bir anı aynı biçimde tutmaya çalışırken, şu anda değişen küçük şeyleri kaçırıyor olabilirsin.", "While trying to keep a moment unchanged, you may miss the small things changing now.", "Ascend", "budist_dusunce", sabitKimlik = "v5_budist_dusunce_08"),
        Soz("Davranışının etkisini düşünmek için büyük bir olay beklemene gerek yok; küçük seçimler de iz bırakır.", "You need not wait for a major event to consider your actions' effects; small choices leave traces too.", "Ascend", "budist_dusunce", sabitKimlik = "v5_budist_dusunce_09"),
        Soz("Bir yargı oluştuğunda, gördüğün ayrıntıyla eklediğin hikâyeyi ayrı ayrı fark edebilirsin.", "When a judgment forms, notice the detail you saw separately from the story you added.", "Ascend", "budist_dusunce", sabitKimlik = "v5_budist_dusunce_10"),
        Soz("Rahatsız edici bir duyguyu inkâr etmeden, bugün bir başkasına nazik davranmayı seçebilirsin.", "Without denying an uncomfortable feeling, you can choose to treat another person kindly today.", "Ascend", "budist_dusunce", sabitKimlik = "v5_budist_dusunce_11"),
        Soz("Bugün dikkatini verdiğin küçük bir iyilik, yalnızca düşüncede kalan niyetinden farklı bir iz bırakır.", "A small kindness you attend to today leaves a different trace from an intention kept only in thought.", "Ascend", "budist_dusunce", sabitKimlik = "v5_budist_dusunce_12"),
        Soz("Bir konuşmayı yönlendirmekten vazgeçtiğinde, karşındakinin asıl derdini daha iyi duyabilirsin.", "When you stop steering a conversation, you may hear more clearly what troubles the other person.", "Ascend", "tao", sabitKimlik = "v5_tao_13"),
        Soz("Masandaki boş bir köşe, yeni bir işe başlamayı kolaylaştırabilir; her alanı doldurmak gerekmiyor.", "An empty corner of your desk can make starting something easier; not every space needs filling.", "Ascend", "tao", sabitKimlik = "v5_tao_14"),
        Soz("Bir aksilikte hızını artırmadan önce, izlediğin yolu değiştirme ihtimalini de düşün.", "Before speeding up in response to a setback, consider whether a different route might help.", "Ascend", "tao", sabitKimlik = "v5_tao_15"),
